        for (int j = 1; j < n - i; j++) {
            if (tytuly.get(j - 1).compareTo(tytuly.get(j)) > 0) {
                String tmp = tytuly.get(j - 1);
                tytuly.set(j - 1, tytuly.get(j));
                tytuly.set(j, tmp);
            }
        }
    }
}

